    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
    max-width: 500px;
    padding: 2rem;
}

/* Focus visible on dialog backdrop */
dialog::backdrop {
    background: rgba(0, 0, 0, 0.7);
    animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

/* Dialog Heading */
dialog h2 {
    font-size: 1.75rem;
    margin-bottom: 1rem;
    color: #ffffff;
    font-weight: 600;
}

/* Dialog Body */
dialog p {
    margin-bottom: 1.5rem;
    color: #b0b0b0;
    line-height: 1.7;
}

/* Dialog Actions */
.dialog-actions {
