+const { chromium } = require('playwright');
+const fs = require('fs');
+const path = require('path');
+const AxeBuilder = require('@axe-core/playwright');
+
+async function runAccessibilityTests() {
+    let browser;
+    try {
+        browser = await chromium.launch();
+        const page = await browser.newPage();
+        const htmlPath = path.resolve(__dirname, 'index.html');
+        const htmlContent = fs.readFileSync(htmlPath, 'utf-8');
+        
+        await page.setContent(htmlContent, { waitUntil: 'load' });
+        
+        // Wait for scripts to execute
+        await page.waitForTimeout(500);
+        
+        // Run axe accessibility tests
+        const results = await new AxeBuilder({ page }).analyze();
+        
+        // Separate WCAG violations from best-practice issues
+        const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
+        const bpIssues = results.violations.filter(v => v.tags.includes('best-practice'));
+        
+        console.log(JSON.stringify({
+            wcag: wcagViolations.map(v => ({
+                id: v.id,
+                impact: v.impact,
+                description: v.description,
+                targets: v.nodes.map(n => n.target)
+            })),
+            bestPractice: bpIssues.map(v => ({
+                id: v.id,
+                description: v.description,
+                targets: v.nodes.map(n => n.target)
+            }))
+        }, null, 2));
+        
+        await browser.close();
+        return wcagViolations.length === 0;
+    } catch (error) {
+        console.error('Test error:', error.message);
+        if (browser) await browser.close();
+        return false;
+    }
+}
+
+runAccessibilityTests().then(success => process.exit(success ? 0 : 1));
+
")

