const { JSDOM } = require('jsdom');
const fs = require('fs');

async function runAccessibilityTests() {
    try {
        const htmlContent = fs.readFileSync('./index.html', 'utf-8');
        const axeSource = fs.readFileSync('/tmp/axe.min.js', 'utf-8');

        const dom = new JSDOM(htmlContent, {
            url: 'http://localhost',
            runScripts: 'outside-only',
            resources: 'usable'
        });

        const { window } = dom;

        // Execute app.js to render the DOM
        const appCode = fs.readFileSync('./app.js', 'utf-8');
        window.eval(appCode);

        // Inject axe
        window.eval(axeSource);

        // Run axe
        const results = await window.axe.run(window.document);

        // Separate violations by type
        const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
        const bpIssues = results.violations.filter(v => v.tags.includes('best-practice'));

        console.log(JSON.stringify({
            wcag: wcagViolations.map(v => ({
                id: v.id,
                impact: v.impact,
                description: v.description,
                targets: v.nodes.map(n => n.target || n.html)
            })),
            bestPractice: bpIssues.map(v => ({
                id: v.id,
                description: v.description,
                targets: v.nodes.map(n => n.target || n.html)
            }))
        }, null, 2));

        return wcagViolations.length === 0;
    } catch (error) {
        console.error('Error:', error.message);
        console.error(error.stack);
        return false;
    }
}

runAccessibilityTests().then(success => {
    process.exit(success ? 0 : 1);
});

