        window.eval(appCode);

        // Inject axe
        window.eval(axeSource);

        // Test 1: Initial state
        console.log('Test 1: Initial Page State');
        let results = await window.axe.run(window.document);
        let wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
