        console.log(`  WCAG violations: ${wcagViolations.length}`);
        console.log(`  Best-practice issues: ${bpIssues.length}`);

        if (wcagViolations.length > 0) {
            console.log('  WCAG Issues:');
            wcagViolations.forEach(v => {
                console.log(`    - ${v.id} (${v.impact}): ${v.description}`);
                v.nodes.forEach(n => console.log(`      Target: ${n.target}`));
            });
        }

        // Test 2: Verify required elements exist
        console.log('\nTest 2: Required Elements');
        const dialog = window.document.querySelector('dialog');
        const triggers = window.document.querySelectorAll('.trigger');
        const h1 = window.document.querySelector('h1');

        console.log(`  Dialog element found: ${!!dialog}`);
        console.log(`  Trigger buttons found: ${triggers.length}`);
        console.log(`  H1 heading found: ${!!h1}`);

        // Test 3: Dialog accessibility attributes
        console.log('\nTest 3: Dialog Accessibility Attributes');
        if (dialog) {
            console.log(`  Dialog has aria-labelledby: ${dialog.hasAttribute('aria-labelledby')}`);
            console.log(`  Dialog has aria-describedby: ${dialog.hasAttribute('aria-describedby')}`);
            console.log(`  Dialog id: ${dialog.id}`);
        }

        // Test 4: Keyboard accessibility
        console.log('\nTest 4: Keyboard Operability');
        const buttons = window.document.querySelectorAll('button');
        console.log(`  Total buttons: ${buttons.length}`);
        let focusableCount = 0;
        buttons.forEach(btn => {
            const canFocus = !btn.hasAttribute('disabled') && btn.offsetParent !== null;
            if (canFocus) focusableCount++;
        });
        console.log(`  Focusable buttons: ${focusableCount}`);

        // Test 5: With dialog open (simulated)
        console.log('\nTest 5: Dialog Open State');
        if (dialog) {
            try {
                dialog.showModal();
                console.log(`  Dialog opened successfully`);

                // Run axe on open state
                results = await window.axe.run(window.document);
                wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
                bpIssues = results.violations.filter(v => v.tags.includes('best-practice'));

                console.log(`  WCAG violations (open): ${wcagViolations.length}`);
                console.log(`  Best-practice issues (open): ${bpIssues.length}`);

                dialog.close();
            } catch (e) {
                console.log(`  Dialog operation not available in jsdom (expected)`);
            }
        }

        // Final Summary
        console.log('\n=== Final Result ===');
        results = await window.axe.run(window.document);
        wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
        const hasIssues = wcagViolations.length > 0;
        console.log(`Status: ${hasIssues ? 'FAILED' : 'PASSED'}`);
        console.log(`WCAG violations: ${wcagViolations.length}`);
        console.log(`Best-practice issues: ${results.violations.filter(v => v.tags.includes('best-practice')).length}`);

        return !hasIssues;
    } catch (error) {
        console.error('Error:', error.message);
        console.error(error.stack);
        return false;
    }
}

runComprehensiveTests().then(success => {
    process.exit(success ? 0 : 1);
});
