 // Sample image data
 const IMAGES = [
     { id: 1, name: 'Mountain Vista', emoji: '🏔️', date: 'Mar 15, 2024' },
     { id: 2, name: 'Ocean Waves', emoji: '🌊', date: 'Mar 12, 2024' },
     { id: 3, name: 'Forest Path', emoji: '🌲', date: 'Mar 10, 2024' },
     { id: 4, name: 'Desert Sunset', emoji: '🏜️', date: 'Mar 08, 2024' },
     { id: 5, name: 'Northern Lights', emoji: '🌌', date: 'Mar 05, 2024' },
     { id: 6, name: 'Flower Garden', emoji: '🌸', date: 'Mar 01, 2024' },
 ];

 // Component: Image Card
 function ImageCard(image) {
     const cardDiv = document.createElement('div');
     cardDiv.className = 'image-card';

     cardDiv.innerHTML = `
         <div class="image-placeholder">${image.emoji}</div>
         <div class="image-info">
             <div class="image-name">${escapeHtml(image.name)}</div>
             <div class="image-date">${escapeHtml(image.date)}</div>
             <div class="image-actions">
                 <button class="btn-view" type="button">View</button>
                 <button class="trigger" type="button" data-image-id="${image.id}" aria-label="Delete ${escapeHtml(image.name)}">Delete</button>
             </div>
         </div>
     `;

     return cardDiv;
 }

 // Component: Delete Confirmation Dialog
 function DeleteDialog() {
     const dialog = document.createElement('dialog');
     dialog.id = 'delete-confirm-dialog';
     dialog.setAttribute('aria-labelledby', 'delete-dialog-heading');
     dialog.setAttribute('aria-describedby', 'delete-dialog-message');

     dialog.innerHTML = `
         <h2 id="delete-dialog-heading">Delete Image?</h2>
         <p id="delete-dialog-message">This action cannot be undone. The image will be permanently removed from your library.</p>
         <div class="dialog-actions">
             <button type="button" class="btn-cancel" data-action="cancel">Cancel</button>
             <button type="button" class="btn-delete" data-action="delete">Delete Permanently</button>
         </div>
     `;

     return dialog;
 }

 // Component: Gallery
 function Gallery(images) {
     const mainDiv = document.createElement('main');

     const galleryDiv = document.createElement('div');
     galleryDiv.className = 'gallery';

     images.forEach(image => {
         galleryDiv.appendChild(ImageCard(image));
     });

     mainDiv.appendChild(galleryDiv);
     return mainDiv;
 }

 // Component: App
 function App() {
     const appDiv = document.createElement('div');

     // Header
     const header = document.createElement('header');
     header.innerHTML = '<h1>My Image Library</h1>';
     appDiv.appendChild(header);

     // Gallery
     appDiv.appendChild(Gallery(IMAGES));

     // Dialog
     appDiv.appendChild(DeleteDialog());

     return appDiv;
 }

 // Utility: HTML Escape
 function escapeHtml(text) {
     const div = document.createElement('div');
     div.textContent = text;
     return div.innerHTML;
 }

 // Initialize App
 function init() {
     const app = document.getElementById('app');
     app.appendChild(App());

     // Setup modal event listeners
     const dialog = document.getElementById('delete-confirm-dialog');
     let currentImageId = null;

     // Attach click handlers to all delete triggers
     app.addEventListener('click', (e) => {
         if (e.target.classList.contains('trigger')) {
             currentImageId = e.target.getAttribute('data-image-id');
             dialog.showModal();
         }
     });

     // Handle dialog actions
     dialog.addEventListener('click', (e) => {
         if (e.target.getAttribute('data-action') === 'cancel') {
             dialog.close('cancel');
         } else if (e.target.getAttribute('data-action') === 'delete') {
             dialog.close('delete');
         }
     });

     // Handle dialog close
     dialog.addEventListener('close', () => {
         if (dialog.returnValue === 'delete' && currentImageId) {
             handleImageDelete(currentImageId);
         }
         currentImageId = null;
     });

     // Handle Escape key (built-in for native dialog)
 }

 // Handle Image Deletion
 function handleImageDelete(imageId) {
     const imageIndex = IMAGES.findIndex(img => img.id === parseInt(imageId));
     if (imageIndex > -1) {
         const deletedImage = IMAGES.splice(imageIndex, 1)[0];
         const cardToRemove = document.querySelector(`.image-card:has([data-image-id="${imageId}"])`);
         if (cardToRemove) {
             cardToRemove.style.animation = 'fadeOut 0.3s ease';
             setTimeout(() => cardToRemove.remove(), 300);
         }
     }
 }

 // Run on DOM ready
 if (document.readyState === 'loading') {
     document.addEventListener('DOMContentLoaded', init);
 } else {
     init();
 }

